param([Parameter(Mandatory=$true)][string]$Manifest,[Parameter(Mandatory=$true)][ValidateSet("YES")][string]$ConfirmSchemaCompatibility,[string]$EnvironmentFile=".env.staging")
$ErrorActionPreference="Stop"; if($ConfirmSchemaCompatibility -ne "YES"){throw "Explicit schema compatibility confirmation required"}; $Release=Get-Content $Manifest -Raw|ConvertFrom-Json; if($Release.migration_components.Count -gt 0){Write-Warning "No DB downgrade will run. Confirm current schema supports target images or forward-fix."}; python .\scripts\render-release-env.py $Manifest --output .\.env.release; if(-not $env:STAGING_COMPOSE_FILES){throw "STAGING_COMPOSE_FILES required"}; $Compose=@("compose"); foreach($f in ($env:STAGING_COMPOSE_FILES -split ";")){$Compose+=@("-f",$f)}; $Compose+=@("--env-file",$EnvironmentFile,"--env-file",".\.env.release"); docker @($Compose+@("pull")); if($LASTEXITCODE -ne 0){throw "pull failed"}; docker @($Compose+@("up","-d","--remove-orphans")); if($LASTEXITCODE -ne 0){throw "rollback failed"}; python .\scripts\wait-for-health.py $env:STAGING_HEALTH_URL --timeout 180
